Here is the commit message:
USB: serial: io_ti: fix heap overflow in get_manuf_info()

get_manuf_info() reads le16_to_cpu(rom_desc->Size) bytes from the
device I2C EEPROM into a buffer allocated with kmalloc_obj(), which
is sizeof(struct edge_ti_manuf_descriptor) = 10 bytes.

The Size field comes from the device and is only validated (in
check_i2c_image()) to make sure the descriptor fits within
TI_MAX_I2C_SIZE (16384 bytes), not against the destination buffer size.
A malicious USB device can therefore set Size to any value up to 16377,
causing a heap overflow of up to 16367 bytes when plugged into a host
running this driver.

valid_csum() is called after read_rom() and also iterates
buffer[0..Size-1], compounding the out-of-bounds access.

Fix by rejecting descriptors with unexpected length before calling
read_rom().

Fixes: 1da177e4c3f4 ("Linux-2.6.12-rc2")
Cc: stable@vger.kernel.org
Signed-off-by: Adrian Korwel <adriank20047@gmail.com>
[ johan: amend commit message; also check for short descriptors ]
Signed-off-by: Johan Hovold <johan@kernel.org>

Here is the root cause:
The `get_manuf_info()` function in `drivers/usb/serial/io_ti.c` reads a `Size` field from the device's I2C EEPROM descriptor without verifying it matches the expected size of the destination buffer (`sizeof(struct edge_ti_manuf_descriptor)` = 10 bytes). The only validation checks that the descriptor fits within the maximum I2C size (16384 bytes), not against the buffer size. This allows a malicious USB device to set `Size` to a value up to 16377, causing a heap overflow when `read_rom()` copies that many bytes into the fixed-size buffer. Additionally, `valid_csum()` later iterates over `buffer[0..Size-1]`, compounding the out-of-bounds access.

Here is the patch:

 static int get_manuf_info(struct edgeport_serial *serial, u8 *buffer)
 {
 	int status;
 	int start_address;
 	struct ti_i2c_desc *rom_desc;
 	struct edge_ti_manuf_descriptor *desc;
 	struct device *dev = &serial->serial->dev->dev;

 	rom_desc = kmalloc_obj(*rom_desc);
 	if (!rom_desc)
 		return -ENOMEM;

 	start_address = get_descriptor_addr(serial, I2C_DESC_TYPE_ION,
 								rom_desc);

 	if (!start_address) {
 		dev_dbg(dev, "%s - Edge Descriptor not found in I2C\n", __func__);
 		status = -ENODEV;
 		goto exit;
 	}

 	/* Read the descriptor data */
+	if (le16_to_cpu(rom_desc->Size) != sizeof(struct edge_ti_manuf_descriptor)) {
+		dev_err(dev, "unexpected Edge descriptor length: %u\n",
+			le16_to_cpu(rom_desc->Size));
+		status = -EINVAL;
+		goto exit;
+	}
 	status = read_rom(serial, start_address+sizeof(struct ti_i2c_desc),
 					le16_to_cpu(rom_desc->Size), buffer);
 	if (status)
 		goto exit;

 	status = valid_csum(rom_desc, buffer);

 	desc = (struct edge_ti_manuf_descriptor *)buffer;
 	dev_dbg(dev, "%s - IonConfig      0x%x\n", __func__, desc->IonConfig);
 	dev_dbg(dev, "%s - Version          %d\n", __func__, desc->Version);
 	dev_dbg(dev, "%s - Cpu/Board      0x%x\n", __func__, desc->CpuRev_BoardRev);
 	dev_dbg(dev, "%s - NumPorts         %d\n", __func__, desc->NumPorts);
 	dev_dbg(dev, "%s - NumVirtualPorts  %d\n", __func__, desc->NumVirtualPorts);
 	dev_dbg(dev, "%s - TotalPorts       %d\n", __func__, desc->TotalPorts);

 exit:
 	kfree(rom_desc);
 	return status;
 }



