+		dev_err(dev, "unexpected Edge descriptor length: %u\n",
+			le16_to_cpu(rom_desc->Size));
+		status = -EINVAL;
+		goto exit;
+	}
Reason:
This check rejects descriptors whose `Size` field does not exactly match the expected size of the destination buffer (`sizeof(struct edge_ti_manuf_descriptor)` = 10 bytes). By verifying the length before calling `read_rom()`, the heap overflow and subsequent out-of-bounds access in `valid_csum()` are prevented.

